const { writeFileSync, mkdirSync, existsSync } = await import('node:fs');
const path = (await import('node:path')).default;
const input = process.env.INPUT_PATH;
const output = process.env.OUTPUT_PATH;
if (!input) throw new Error('Missing INPUT_PATH');
if (!output) throw new Error('Missing OUTPUT_PATH');
globalThis.inputPath = input;
globalThis.outputPath = output;
const outDir = path.dirname(output);
if (!existsSync(outDir)) {
  mkdirSync(outDir, { recursive: true });
}

const mod = await import('docx2pdf-converter');
const converter = mod.default || mod;
converter.convert(globalThis.inputPath, globalThis.outputPath);
